using UnityEngine;
using LWS.TruckSports;
namespace LWS.TruckTerrierRacing {
public sealed class TerrierRacer:MonoBehaviour {
 public TerrierMatch match;public SportsEventTruck truck;public int slot;public bool Alive{get;private set;}public Vector3 Incoming{get;private set;}public int Jumps{get;private set;}public float LastJump{get;private set;}
 float cooldown,tipped,blocked,missedAge,lostMomentum,lastObstacle=-100,obstacleZ;Vector3 previous;public bool Finished{get;private set;}
 public void Finish(){Finished=true;foreach(var wheel in truck.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=0;wheel.SteerAngle=0;}}public void Prepare(Vector3 p){truck.slot=slot;truck.visuals.gameObject.SetActive(true);truck.Prepare(p,match.course.DrivingRotation);truck.Power(false);truck.body.isKinematic=true;Alive=true;Finished=false;Jumps=0;cooldown=tipped=blocked=missedAge=lostMomentum=0;lastObstacle=-100;previous=p;}
 public void Release(){truck.body.isKinematic=false;truck.Power(true);}
 public bool Jump(bool requested){if(!requested||cooldown>0||!truck.Grounded||!Alive)return false;cooldown=.85f;LastJump=match.HeatTime;Jumps++;truck.body.AddForce(Vector3.up*6.2f,ForceMode.VelocityChange);match.JumpEvent(slot);match.Pulse(slot,.12f,.07f);return true;}
 public void Step(Vector2 input,bool jump,float dt){if(!Alive)return;if(Finished){foreach(var wheel in truck.wheels){wheel.MotorTorque=0;wheel.BrakeTorque=6;wheel.SteerAngle=0;}Incoming=truck.body.linearVelocity;return;}cooldown=Mathf.Max(0,cooldown-dt);truck.grip=1.2f*match.course.Grip(truck.body.position);truck.TickDrive(input);Jump(jump);var body=truck.body;body.AddForce(match.course.weather.Flow*(truck.Grounded?.15f:.55f),ForceMode.Acceleration);if(truck.Grounded){var up=body.rotation*Vector3.up;if(Vector3.Dot(up,Vector3.up)<.5f)tipped+=dt;else tipped=0;if(tipped>1)body.AddTorque(Vector3.Cross(up,Vector3.up)*4-body.angularVelocity,ForceMode.Acceleration);}if((body.position-previous).sqrMagnitude<.0001f&&input.sqrMagnitude>.1f)blocked+=dt;else blocked=Mathf.Max(0,blocked-dt);previous=body.position;Incoming=body.linearVelocity;bool failedJump=match.HeatTime-lastObstacle<3&&Mathf.Abs(match.course.Local(body.position).z-obstacleZ)<4&&Vector3.ProjectOnPlane(Incoming,Vector3.up).magnitude<2.5f;if(failedJump)missedAge+=dt;else missedAge=Mathf.Max(0,missedAge-dt*2);bool stranded=match.HeatTime>4&&(Jumps>0||match.HeatTime-lastObstacle<8)&&Incoming.sqrMagnitude<2.25f&&(Vector3.Dot(transform.up,Vector3.up)<.45f||match.HeatTime-lastObstacle<8||blocked>1);lostMomentum=stranded?lostMomentum+dt:Mathf.Max(0,lostMomentum-dt*2);if(missedAge>=1.1f||lostMomentum>=2.5f){match.QueueWreck(slot,Time.fixedTime);return;}var local=match.course.Local(body.position);if(local.y< -8||Mathf.Abs(local.x)>match.course.HalfWidth(local.z)+4||local.z>match.course.Length+18)match.QueueWreck(slot,Time.fixedTime);}
 public float Blocked=>blocked;
 public void Wreck(){if(!Alive)return;Alive=false;truck.Power(false);truck.body.detectCollisions=false;truck.body.isKinematic=true;truck.visuals.gameObject.SetActive(false);truck.StopSound();}
 void OnCollisionStay(Collision c){if(!Alive||Finished||match.Phase!=TerrierPhase.Race||c.collider.GetComponent<TerrierJumpObstacle>()==null)return;if(match.HeatTime-lastObstacle>.1f)obstacleZ=match.course.Local(truck.body.position).z;lastObstacle=match.HeatTime;}
 void OnCollisionEnter(Collision c){if(!Alive||match.Phase!=TerrierPhase.Race)return;if(Finished)return;if(c.collider.GetComponent<TerrierJumpObstacle>()!=null){for(int i=0;i<c.contactCount;i++)if(Mathf.Abs(c.GetContact(i).normal.z)>.25f&&Incoming.z>2.5f){lastObstacle=match.HeatTime;obstacleZ=match.course.Local(truck.body.position).z;break;}}var wall=c.collider.GetComponent<TerrierFinishWall>();if(wall==null)return;for(int i=0;i<c.contactCount;i++)if(TerrierRules.FatalWall(Incoming,c.GetContact(i).normal)){match.QueueWreck(slot,Time.fixedTime+Time.fixedDeltaTime);return;}}
}

}
